SetColumns(0);SetQuitOnError(true);SetNthreads(1);SetMemoryLimit(7*10^9);Alarm(1000);tt:=Cputime();load "work/deg10/continuation_20261031b/C48/inputs/portable_inputs.m";root:="work/deg10/continuation_20261031b/C48/";k:=GF(5);PK:=PolynomialRing(k);B<t>:=FunctionField(k);R<Y>:=PolynomialRing(B);
function Rat(v)return B!(PK!v[1])/B!(PK!v[2]);end function;F<y>:=FunctionField(R![Rat(v):v in PortableFieldEquation]);assert Genus(F)eq 13;
function FF(v)return F![Rat(z):z in v];end function;OF:=MaximalOrderFinite(F);OI:=MaximalOrderInfinite(F);fb:=[];for i in[1..#PortableDegrees]do O:=PortableFlags[i]eq 1 select OF else OI;J:=ideal<O|[FF(v):v in PortableIdealBases[i]]>;p:=Place(J);assert Degree(p)eq PortableDegrees[i];Append(~fb,p);end for;A:=Divisor(fb[801]);assert Degree(A)eq 1;Z:=FreeAbelianGroup(9);G,q:=quo<Z|[Z!v:v in PortableRelations]>;fc:=[q(Z!v):v in PortableClasses];ac:=fc[801];coords:=[FF(v):v in PortableCoordinates];
function FromValues(vals)
 K:=Parent(vals[1]);e:=LCM([Degree(MinimalPolynomial(v,k)):v in vals]);for z in[[1,0],[0,1]]cat[[1,n]:n in[1..4]]do gen:=z[1]*vals[1]+z[2]*vals[2];pol:=MinimalPolynomial(gen,k);if Degree(pol)eq e then bits:=z;break;end if;end for;M:=Matrix(k,[Eltseq(gen^i,k):i in[0..e-1]]);cc:=[Eltseq(Solution(M,Vector(k,Eltseq(v,k)))):v in vals];gg:=bits[1]*coords[1]+bits[2]*coords[2];fs:=[Evaluate(pol,gg)]cat[coords[j]-Evaluate(PK!cc[j],gg):j in[1,2]];J:=ideal<OF|fs>;pp:=[Place(z[1]):z in Factorization(J)|z[2]gt 0];if #pp eq 0 then J:=ideal<OI|fs>;pp:=[Place(z[1]):z in Factorization(J)|z[2]gt 0];end if;assert #pp eq 1;P:=pp[1];assert Degree(P)eq e and &and[f eq 0 or Valuation(f,P)gt 0:f in fs];vv:=[Evaluate(z,P):z in coords];g:=bits[1]*vv[1]+bits[2]*vv[2];assert MinimalPolynomial(g,k)eq pol and &and[vv[j]eq Evaluate(PK!cc[j],g):j in[1,2]];return P;
end function;
function SD(v)return &+[DivisorGroup(F)|z[2]*Divisor(fb[z[1]]):z in v];end function;
function SC(v)return &+[G|z[2]*fc[z[1]]:z in v];end function;
packet:=eval Read(root cat KIND cat Sprintf("_class_s%o.m",SHARD));W:=eval Read(root cat KIND cat Sprintf("_class_s%o_witnesses.m",SHARD));src:=eval Read(root cat(KIND eq "high"select "high_character_targets.m"else "low_character_targets.m"));fields:=AssociativeArray();for z in src[1]do fields[z[1]]:=ext<k|PK!z[2]>;end for;wi:=0;direct:=0;out:=[* *];
for row in packet[1]do ci,d,e,n,clvec:=Explode([*row[j]:j in[1..5]*]);r:=src[2][ci];assert r[1]eq d and r[3]eq e and r[4]eq n;K:=fields[d];vals:=[Evaluate(PK!r[2][1..d],K.1),Evaluate(PK!r[2][d+1..2*d],K.1)];P:=FromValues(vals);assert Degree(P)eq e and n*e eq d;ii:=e le 5 select Index(fb,P)else 0;
 if ii gt 0 then cl0:=fc[ii]-e*ac;used:=0;direct+:=1;
 else wi+:=1;assert wi le #W;v:=W[wi];assert #v eq 7 and v[2]eq 0;E:=SD(v[4]);R:=SD(v[5]);assert SD(v[6])eq A and v[1]eq e and Degree(E)eq 13 and Degree(R)eq 13;assert &and[z[2]ge 0:z in v[4]]and &and[z[2]ge 0:z in v[5]];b:=FF(v[7]);assert b ne 0;IE,JE:=Ideals(E);IR,JR:=Ideals(R);ID,JD:=Ideals(Divisor(P)-e*A);assert IE/(IR*(b*OF))eq ID and JE/(JR*(b*OI))eq JD;cl0:=SC(v[4])-SC(v[5]);assert cl0 eq q(Z!v[3]);used:=wi;
 end if;assert n*cl0 eq q(Z!clvec);Append(~out,[ci,d,e,n,ii,used]);if #out mod 100 eq 0 then print "D31B_C48_CLASS_IDEAL_REPLAY_PROGRESS",KIND,SHARD,#out,wi,direct,Cputime(tt);end if;
end for;assert wi eq #W;Write(root cat KIND cat Sprintf("_class_native_s%o.m",SHARD),Sprint([*out,[#out,wi,direct]*]):Overwrite:=true);print "D31B_C48_CLASS_IDEAL_REPLAY_COMPLETE",KIND,SHARD,#out,wi,direct,Cputime(tt);quit;
